package com.immersio.upload.service; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.util.*;
@Service public class StorageService {public String store(MultipartFile file,String folder)throws IOException{String dir=folder==null||folder.isBlank()?"uploads": "uploads/"+folder.replaceAll("[^a-zA-Z0-9/_-]","");Path root=Paths.get(".").toAbsolutePath().normalize().resolve(dir).normalize();if(!root.startsWith(Paths.get(".").toAbsolutePath().normalize()))throw new IOException("Invalid folder");Files.createDirectories(root);String name=UUID.randomUUID()+"-"+(file.getOriginalFilename()==null?"file":Path.of(file.getOriginalFilename()).getFileName());Path out=root.resolve(name);file.transferTo(out);return "/"+dir+"/"+name;}}
